import{_ as a,o as t,c as i,al as o}from"./chunks/framework.7vp1BMOE.js";const c=JSON.parse('{"title":"Rover Configuration/Tuning","description":"","frontmatter":{},"headers":[],"relativePath":"en/config_rover/index.md","filePath":"en/config_rover/index.md"}'),r={name:"en/config_rover/index.md"};function s(n,e,d,l,h,u){return t(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="rover-configuration-tuning" tabindex="-1">Rover Configuration/Tuning <a class="header-anchor" href="#rover-configuration-tuning" aria-label="Permalink to &quot;Rover Configuration/Tuning&quot;">​</a></h1><p>This topic provides a step-by-step guide for setting up your rover.</p><p>Successive steps enable <a href="./../flight_modes_rover/">drive modes</a> with more autopilot support and features:</p><table tabindex="0"><thead><tr><th>Step</th><th>Configuration</th><th>Unlocked PX4 Drive Mode</th></tr></thead><tbody><tr><td>1</td><td><a href="./basic_setup">Basic Setup</a></td><td><a href="./../flight_modes_rover/manual#manual-mode">Full manual mode</a></td></tr><tr><td>2</td><td><a href="./rate_tuning">Rate Tuning</a></td><td><a href="./../flight_modes_rover/manual#acro-mode">Manual acro mode</a></td></tr><tr><td>3</td><td><a href="./attitude_tuning">Attitude Tuning</a></td><td><a href="./../flight_modes_rover/manual#stabilized-mode">Manual stabilized mode</a></td></tr><tr><td>4</td><td><a href="./velocity_tuning">Velocity Tuning</a></td><td><a href="./../flight_modes_rover/manual#manual-mode">Manual position mode</a></td></tr><tr><td>5</td><td><a href="./position_tuning">Position Tuning</a></td><td><a href="./../flight_modes_rover/auto">Auto modes</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A drive mode will only work properly if all the configuration for the preceding modes has been completed.</p></div><h2 id="flashing-the-rover-build" tabindex="-1">Flashing the Rover Build <a class="header-anchor" href="#flashing-the-rover-build" aria-label="Permalink to &quot;Flashing the Rover Build&quot;">​</a></h2><p>Rover is built as a <a href="./../dev_setup/building_px4#px4-make-build-targets">firmware variant</a>, and must be installed as &quot;Custom Firmware&quot; in QGC (other vehicles are present in the default variant).</p><p>The release versions of Rover firmware for different boards are attached to the associated GitHub release tag. For example, you can find <code>px4_fmu-v5x_rover.px4</code> on <a href="https://github.com/PX4/PX4-Autopilot/releases/tag/v1.16.1" target="_blank" rel="noreferrer">PX4-Autopilot/releases/tag/v1.16.1</a>. For the <code>main</code> branch version of Rover you will need to <a href="#building-rover">build the firmware</a>.</p><p>Load the firmware onto your flight controller as &quot;Custom Firmware&quot; (see <a href="./../config/firmware#installing-px4-main-beta-or-custom-firmware">Loading Firmware &gt; Installing PX4 Main, Beta or Custom Firmware</a>).</p><h2 id="building-rover" tabindex="-1">Building Rover <a class="header-anchor" href="#building-rover" aria-label="Permalink to &quot;Building Rover&quot;">​</a></h2><p>Rover is built as the <code>rover</code> <a href="./../dev_setup/building_px4#px4-make-build-targets">firmware variant</a>. What this means is that when building the firmware with the <code>make</code> command, you replace the <code>_default</code> suffix in the configuration target with <code>_rover</code>.</p><p>For example, to build rover for <code>px4_fmu-v6x</code> boards, you would use the following command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_rover</span></span></code></pre></div><p>Note that configuration targets are constructed with the format &quot;VENDOR_MODEL_VARIANT&quot;.</p><p>The built firmware can be installed as custom firmware, as shown above in <a href="#flashing-the-rover-build">Flashing the Rover Build</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can also enable the modules in default builds by adding these lines to your <a href="./../hardware/porting_guide_config">board configuration</a> (e.g. for fmu-v6x you might add them to <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6x/default.px4board" target="_blank" rel="noreferrer"><code>main/boards/px4/fmu-v6x/default.px4board</code></a>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_ROVER_ACKERMANN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_ROVER_DIFFERENTIAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_ROVER_MECANUM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span></code></pre></div><p>Adding the rover modules may lead to flash overflow, in which case you will need to disable modules that you do not plan to use (such as those related to multicopter or fixed wing).</p></div>`,16)])])}const g=a(r,[["render",s]]);export{c as __pageData,g as default};
